import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { orbit, depthRotate, dissolveMorph, displacementTransition, parallaxScroll, magneticCursor, particleEmerge, flyThrough, kineticText } from '@/primitives';
import { createText } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container for this node
  const root = new Group();

  // Plane geometry – size will be driven by texture aspect when loaded
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({ transparent: true });
  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load texture asynchronously; material will be updated when ready
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Apply cinematic primitives if any are listed in config
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const instance = fn(root, prim.params);
        primitiveInstances.push(instance);
      }
    }
  }

  // Event handlers placeholder (no interactions defined for this node)
  root.userData.handlers = {};

  // Cleanup routine – disposes resources and kills any GSAP timelines
  root.userData.cleanup = () => {
    // Dispose material and its texture
    if (material.map) {
      material.map.dispose();
    }
    material.dispose();

    // Dispose geometry
    geometry.dispose();

    // Cleanup primitives
    for (const inst of primitiveInstances) {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    }

    // Kill any GSAP timelines that might have been created (none in this node)
    gsap.globalTimeline.clear();
  };

  return root;
}
